/**
 * A page of cursor-based results.
 */
public struct CursorPage {
    public var records: [RecordResult]
    public var cursor: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(records: [RecordResult], cursor: String?) {
        self.records = records
        self.cursor = cursor
    }
}



extension CursorPage: Equatable, Hashable {
    public static func ==(lhs: CursorPage, rhs: CursorPage) -> Bool {
        if lhs.records != rhs.records {
            return false
        }
        if lhs.cursor != rhs.cursor {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(records)
        hasher.combine(cursor)
    }
}


